function run(db, sql, params = []) { return new Promise((resolve, reject) => db.run(sql, params, function (e) { e ? reject(e) : resolve({ id:this.lastID,changes:this.changes }); })); }
function get(db, sql, params = []) { return new Promise((resolve, reject) => db.get(sql, params, (e, row) => e ? reject(e) : resolve(row || null))); }
function all(db, sql, params = []) { return new Promise((resolve, reject) => db.all(sql, params, (e, rows) => e ? reject(e) : resolve(rows || []))); }
function open() { return new sqlite3.Database(":memory:"); }
async function base(db) {
    await run(db,"PRAGMA foreign_keys=ON");
    await run(db,"CREATE TABLE stores(id INTEGER PRIMARY KEY,store_code TEXT,store_name TEXT,status TEXT)");
    await run(db,"CREATE TABLE store_context(id INTEGER PRIMARY KEY,current_store_id INTEGER)");
    await run(db,"CREATE TABLE supplier_master(id INTEGER PRIMARY KEY,supplier_code TEXT,name TEXT,status TEXT)");
    await run(db,"CREATE TABLE supplier_invoices(id INTEGER PRIMARY KEY,invoice_code TEXT,store_id INTEGER,supplier_id INTEGER,supplier_invoice_number TEXT,supplier_invoice_date TEXT,status TEXT)");
    await run(db,"CREATE TABLE products(id INTEGER PRIMARY KEY,barcode TEXT,sku TEXT,product_name TEXT,brand TEXT,product TEXT,colour TEXT,size TEXT,mrp REAL,active INTEGER,variable_value INTEGER NOT NULL DEFAULT 0)");
    await run(db,"CREATE TABLE inventory_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,barcode TEXT,transaction_type TEXT,quantity INTEGER,reference_type TEXT,reference_id TEXT,supplier_id INTEGER,invoice_no TEXT,remarks TEXT,created_by TEXT,created_at TEXT)");
    await run(db,"CREATE TABLE activities(id INTEGER PRIMARY KEY,activity_date TEXT,activity_time TEXT,category TEXT,action TEXT,details TEXT,user_name TEXT,status TEXT,entity_type TEXT,reference_no TEXT,change_data TEXT,created_at TEXT)");
    await run(db,"INSERT INTO stores VALUES(1,'KL001','Kaira Luxe','ACTIVE')");
    await run(db,"INSERT INTO store_context VALUES(1,1)");
    await run(db,"INSERT INTO supplier_master VALUES(1,'KLSUP000001','JPS & CO','ACTIVE')");
}
async function v5MovementTables(db) {
    await run(db,`CREATE TABLE stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,movement_no TEXT NOT NULL UNIQUE,direction TEXT NOT NULL CHECK(direction IN ('INWARD','OUTWARD')),status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PARTIALLY_POSTED','PENDING_MASTER','COMPLETE','CANCELLED')),supplier_id INTEGER,supplier_name TEXT,invoice_no TEXT,reference_text TEXT,business_date TEXT NOT NULL,reason TEXT,remarks TEXT,idempotency_key TEXT NOT NULL UNIQUE,posted_by TEXT,posted_at TEXT,cancelled_by TEXT,cancelled_at TEXT,cancel_reason TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL)`);
    await run(db,`CREATE TABLE stock_movement_lines(id INTEGER PRIMARY KEY AUTOINCREMENT,movement_id INTEGER NOT NULL,barcode TEXT NOT NULL,scanned_quantity INTEGER NOT NULL CHECK(scanned_quantity>0),recognized_quantity INTEGER NOT NULL DEFAULT 0 CHECK(recognized_quantity>=0 AND recognized_quantity<=scanned_quantity),product_id INTEGER,product_state TEXT NOT NULL DEFAULT 'PENDING_MASTER' CHECK(product_state IN ('READY','PENDING_MASTER')),posting_state TEXT NOT NULL DEFAULT 'UNPOSTED' CHECK(posting_state IN ('UNPOSTED','POSTED')),posted_quantity INTEGER NOT NULL DEFAULT 0 CHECK(posted_quantity>=0 AND posted_quantity<=recognized_quantity),inventory_transaction_id INTEGER,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(movement_id,barcode),CHECK((product_state='PENDING_MASTER' AND product_id IS NULL AND recognized_quantity=0) OR (product_state='READY' AND product_id IS NOT NULL AND recognized_quantity>0)),CHECK((posting_state='UNPOSTED' AND posted_quantity=0) OR (posting_state='POSTED' AND posted_quantity=recognized_quantity)),FOREIGN KEY(movement_id) REFERENCES stock_movements(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(inventory_transaction_id) REFERENCES inventory_transactions(id))`);
    await run(db,"CREATE INDEX idx_stock_movements_date_status ON stock_movements(business_date,status)");
    await run(db,"CREATE INDEX idx_stock_movements_invoice ON stock_movements(supplier_id,invoice_no)");
    await run(db,"CREATE INDEX idx_stock_movement_lines_barcode_state ON stock_movement_lines(barcode,product_state,posting_state)");
    await run(db,"CREATE INDEX idx_stock_movement_lines_product ON stock_movement_lines(product_id)");
}

